/// A salary as a month, a day and an hour, in piastres.
class SalaryRates {
  final PlatformInt64 monthly;
  final PlatformInt64 daily;
  final PlatformInt64 hourly;

  const SalaryRates({
    required this.monthly,
    required this.daily,
    required this.hourly,
  });

  @override
  int get hashCode => monthly.hashCode ^ daily.hashCode ^ hourly.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SalaryRates &&
          runtimeType == other.runtimeType &&
          monthly == other.monthly &&
          daily == other.daily &&
          hourly == other.hourly;
}

/// Who takes an action on a transfer, the capability it needs and the status
/// it leads to.
class TransferStep {
  /// `source` | `destination`
  final String side;

  /// The capability key, e.g. `inventory.transfers.create`.
  final String cap;
  final String next;

  const TransferStep({
    required this.side,
    required this.cap,
    required this.next,
  });

  @override
  int get hashCode => side.hashCode ^ cap.hashCode ^ next.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TransferStep &&
          runtimeType == other.runtimeType &&
          side == other.side &&
          cap == other.cap &&
          next == other.next;
}

/// A unit's base unit and how many of the base one of it is.
class UnitSpec {
  final String base;
  final double factor;

  const UnitSpec({required this.base, required this.factor});

  @override
  int get hashCode => base.hashCode ^ factor.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UnitSpec &&
          runtimeType == other.runtimeType &&
          base == other.base &&
          factor == other.factor;
}
